SELECT r.id FROM conversations r WHERE r.parent_id IS NULL AND r.task_id IN (SELECT id FROM tasks WHERE status IN ('done','closed')) AND ((COALESCE(r.audience,CASE WHEN substr(COALESCE(r.room_key,''),1,13)='live-meeting:' THEN 'meeting' WHEN r.scope='personal' THEN 'personal' WHEN r.scope='shared' THEN 'home' WHEN r.kind='task' AND r.task_id IS NOT NULL THEN 'task' ELSE 'participants' END) IN ('company','team','members') OR (COALESCE(r.audience,CASE WHEN substr(COALESCE(r.room_key,''),1,13)='live-meeting:' THEN 'meeting' WHEN r.scope='personal' THEN 'personal' WHEN r.scope='shared' THEN 'home' WHEN r.kind='task' AND r.task_id IS NOT NULL THEN 'task' ELSE 'participants' END) IN ('personal','participants') AND ((SELECT COUNT(*) FROM thread_members gm WHERE gm.thread_id=r.id)>=3 OR (CASE WHEN json_valid(r.participants) THEN json_array_length(r.participants) ELSE 0 END)>=3))) AND (COALESCE(r.root_id,r.id) IN (SELECT r.id FROM conversations r WHERE CASE WHEN r.audience IS NULL THEN (CASE COALESCE(r.scope,'direct') WHEN 'personal' THEN COALESCE(r.owner_id,(SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1))='human:ben' AND (COALESCE(r.room_key,'')<>'ceo' OR 0) WHEN 'shared' THEN (CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN substr(r.room_key,1,instr(r.room_key||':',':')-1) ELSE (SELECT substr(value,5) FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'bot:%' LIMIT 1) END) IN ('cpo','ops','product-design') ELSE EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value='human:ben') END OR (r.kind='task' AND r.task_id IS NOT NULL)) ELSE CASE r.audience WHEN 'company' THEN 1 WHEN 'team' THEN r.audience_group_id IN () WHEN 'members' THEN EXISTS (SELECT 1 FROM thread_members tm WHERE tm.thread_id=r.id AND tm.actor IN ('human:ben')) WHEN 'task' THEN r.task_id IS NOT NULL WHEN 'home' THEN COALESCE(r.owner_id,CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN 'bot:'||substr(r.room_key,1,instr(r.room_key||':',':')-1) WHEN r.scope='personal' THEN (SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1) END) IS NOT NULL AND COALESCE(r.owner_id,CASE WHEN r.scope='shared' AND COALESCE(r.room_key,'')<>'' THEN 'bot:'||substr(r.room_key,1,instr(r.room_key||':',':')-1) WHEN r.scope='personal' THEN (SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1) END) NOT IN () WHEN 'personal' THEN ((COALESCE(r.room_key,'')<>'' AND COALESCE(r.owner_id,(SELECT value FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value LIKE 'human:%' LIMIT 1))='human:ben') OR EXISTS (SELECT 1 FROM thread_members tm WHERE tm.thread_id=r.id AND tm.actor IN ('human:ben'))) AND (COALESCE(r.room_key,'')<>'ceo' OR 0) WHEN 'participants' THEN EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(r.participants) THEN r.participants END) WHERE value='human:ben') WHEN 'meeting' THEN 0 ELSE 0 END END) OR r.id IN (SELECT lm.conversation_id FROM messages lm JOIN conversations lr ON lr.id=lm.conversation_id WHERE lr.audience='home' AND lm.legacy_audience IN ('shared:cpo','shared:ops','shared:product-design'))) AND (r.task_id IS NULL OR r.task_id IN (SELECT id FROM tasks)))
